const LAYOUT=[1,2,3,0xC,4,5,6,0xD,7,8,9,0xE,0xA,0,0xB,0xF];
class Chip8{
 constructor(){this.keys=new Array(16).fill(false);this.reset();}
 reset(){this.mem=new Uint8Array(4096);this.mem.set(FONT,0x50);this.V=new Uint8Array(16);this.I=0;this.pc=0x200;
  this.stack=[];this.dt=0;this.st=0;this.gfx=new Uint8Array(2048);this.waitReg=-1;this.draw=true;
