 tick(){if(this.dt>0)this.dt--;if(this.st>0)this.st--;}
 static dis(o){const x=(o>>8)&15,y=(o>>4)&15,n=o&15,nn=o&255,nnn=o&0xFFF,h=v=>v.toString(16).toUpperCase();
  switch(o>>12){
