  case 8:{const m={0:'LD',1:'OR',2:'AND',3:'XOR',4:'ADD',5:'SUB',6:'SHR',7:'SUBN',0xE:'SHL'}[n];return m?`${m} V${h(x)}, V${h(y)}`:'???';}
