  case 0xC:return`RND V${h(x)}, ${h(nn)}`;case 0xD:return`DRW V${h(x)}, V${h(y)}, ${n}`;
  case 0xE:if(nn==0x9E)return`SKP V${h(x)}`;if(nn==0xA1)return`SKNP V${h(x)}`;return'???';
  case 0xF:{const m={7:`LD V${h(x)}, DT`,0xA:`LD V${h(x)}, K`,0x15:`LD DT, V${h(x)}`,0x18:`LD ST, V${h(x)}`,0x1E:`ADD I, V${h(x)}`,0x29:`LD F, V${h(x)}`,0x33:`LD B, V${h(x)}`,0x55:`LD [I], V${h(x)}`,0x65:`LD V${h(x)}, [I]`}[nn];return m||'???';}
  }return'???';}
 keyPress(k){this.keys[k]=true;if(this.waitReg>=0){this.V[this.waitReg]=k;this.waitReg=-1;}}
 step(){
