  switch(o>>12){
  case 0:if(o==0xE0){this.gfx.fill(0);this.draw=true;}else if(o==0xEE){if(this.stack.length)this.pc=this.stack.pop();}break;
  case 1:this.pc=nnn;break;
  case 2:if(this.stack.length<16)this.stack.push(this.pc);this.pc=nnn;break;
  case 3:if(V[x]==nn)this.pc+=2;break;
  case 4:if(V[x]!=nn)this.pc+=2;break;
  case 5:if(V[x]==V[y])this.pc+=2;break;
  case 6:V[x]=nn;break;
  case 7:V[x]=(V[x]+nn)&255;break;
  case 8:{let r,f;switch(n){
   case 0:V[x]=V[y];break;
   case 1:V[x]|=V[y];break;case 2:V[x]&=V[y];break;case 3:V[x]^=V[y];break;
   case 4:r=V[x]+V[y];V[x]=r&255;V[15]=r>255?1:0;break;
   case 5:f=V[x]>=V[y]?1:0;V[x]=(V[x]-V[y])&255;V[15]=f;break;
   case 6:f=V[x]&1;V[x]>>=1;V[15]=f;break;
   case 7:f=V[y]>=V[x]?1:0;V[x]=(V[y]-V[x])&255;V[15]=f;break;
   case 0xE:f=V[x]>>7;V[x]=(V[x]<<1)&255;V[15]=f;break;}break;}
  case 9:if(V[x]!=V[y])this.pc+=2;break;
  case 0xA:this.I=nnn;break;
  case 0xB:this.pc=(nnn+V[0])&0xFFF;break;
  case 0xC:V[x]=(Math.random()*256)&nn;break;
  case 0xD:{const px=V[x]&63,py=V[y]&31;V[15]=0;
   for(let r=0;r<n;r++){const b=this.mem[(this.I+r)&0xFFF];
    for(let c=0;c<8;c++)if(b&(0x80>>c)){const X=(px+c)&63,Y=(py+r)&31,i=Y*64+X;
