   this.draw=true;break;}
  case 0xE:if(nn==0x9E){if(this.keys[V[x]&15])this.pc+=2;}else if(nn==0xA1){if(!this.keys[V[x]&15])this.pc+=2;}break;
  case 0xF:switch(nn){
   case 7:V[x]=this.dt;break;
   case 0xA:this.waitReg=x;break;
   case 0x15:this.dt=V[x];break;case 0x18:this.st=V[x];break;
   case 0x1E:this.I=(this.I+V[x])&0xFFFF;break;
   case 0x29:this.I=0x50+(V[x]&15)*5;break;
   case 0x33:{const v=V[x];this.mem[this.I&0xFFF]=Math.floor(v/100);this.mem[(this.I+1)&0xFFF]=Math.floor(v/10)%10;this.mem[(this.I+2)&0xFFF]=v%10;break;}
   case 0x55:for(let i=0;i<=x;i++)this.mem[(this.I+i)&0xFFF]=V[i];break;
   case 0x65:for(let i=0;i<=x;i++)V[i]=this.mem[(this.I+i)&0xFFF];break;}
   break;}
 }
}
// Build demo ROM with sprite at 0x230
const demoRom=new Uint8Array(0x38);demoRom.set(DEMO.slice(0,DEMO.length-8),0);demoRom.set(DEMO.slice(-8),0x30);
const $=id=>document.getElementById(id),cv=$('scr'),ctx=cv.getContext('2d'),img=ctx.createImageData(64,32);
const cpu=new Chip8();cpu.load(demoRom);
