LAYOUT.forEach(k=>{const d=document.createElement('div');const kb=Object.keys(KEYMAP).find(c=>KEYMAP[c]==k);
 d.innerHTML=`<b>${k.toString(16).toUpperCase()}</b><br>[${kb.toUpperCase()}]`;
 const dn=e=>{e.preventDefault();cpu.keyPress(k);upd()},up=e=>{e.preventDefault();cpu.keys[k]=false;upd()};
 d.onmousedown=dn;d.onmouseup=up;d.onmouseleave=up;d.ontouchstart=dn;d.ontouchend=up;
 $('keys').appendChild(d);kdiv[k]=d;});
function hex(v,w){return v.toString(16).toUpperCase().padStart(w,'0');}
